"use client";

import { useState } from "react";
import { PhaserPanel } from "@/components/audio-ui/devices/phaser/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";
import { DEMO_TEMPO } from "@/lib/demo-sound";
import {
  type PhaserState,
  phaserDevice,
} from "@/components/audio-ui/devices/phaser/device";
import { createPhaserEngine } from "@/components/audio-ui/devices/phaser/engine";

const MASTER_VOLUME = 0.7;
/** The loop's own tempo, so a synced rate moves with its beat. */
const CONTEXT = { tempo: DEMO_TEMPO };

/**
 * A phaser and flanger you can plug in: its state, a panel that draws the sweep and an engine that plays it, each its own file. Play the loop, switch the mode and turn the rate and the feedback.
 */
export function BlockPhaser() {
  const [state, setState] = useState<PhaserState>(() =>
    phaserDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    context: CONTEXT,
    create: createPhaserEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-4xl h-full w-full min-w-0">
      <PhaserPanel onValueChange={setState} tempo={DEMO_TEMPO} value={state} />
    </div>
  );
}
